import{z as i,x as s,o as e,c as p,q as t,j as o,D as a,d as B,s as r,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"排放交易体系的深化","description":"","frontmatter":{"title":"排放交易体系的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/env-ets-deep.md","filePath":"econ/env-ets-deep.md","lastUpdated":1791063341000}'),d={name:"econ/env-ets-deep.md"};function c(m,E,D,C,F,h){const n=s("Mermaid");return e(),p("div",null,[E[2]||(E[2]=t('<h1 id="排放交易体系的深化" tabindex="-1">排放交易体系的深化 <a class="header-anchor" href="#排放交易体系的深化" aria-label="Permalink to &quot;排放交易体系的深化&quot;">​</a></h1><div class="epigraph"><p>帽子好定，稀缺难信：许可体系的深水区不是总量怎么算，而是让市场相信十年后的帽子还在。</p><footer>—— 据 Montgomery, Journal of Economic Theory, 1972；Roberts &amp; Spence, Journal of Public Economics, 1976 整理</footer></div><p><a href="/econ/ec-map">上一课</a>把「经济数据与计算」收束：构念、覆盖、偏校、复现、成本五问缺一即零，识别的语言归计量、工程的接口归计算机栏，乘积才是可信实证。<a href="/econ/cap-and-trade">总量管制与许可证</a>的纸面设计假定帽子一次选定、竞争市场自动对齐 MAC；真实体系要活几十年，难题从「帽子选多少」变成「稀缺性能不能跨年可信」。本课是「环境与能源经济学」的第一课，后面六课默认读完本课：先看帽子在日历里如何失守，再看把它钉回规则的三件装置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Montgomery 的均衡是一次性的。放进日历，三件事坏掉。其一，信息按年到达：选帽时对减排成本的猜测逐年修正，2006 年春欧盟公布 2005 年核证排放，超发一目了然，第一期配额价格从约 30 欧元跌向近零——帽子的真实稀缺度是核证数据的函数，不是立法文本的函数。其二，政府不可承诺：成本冲击一来，放松帽子在政治上总是诱人的，市场一旦预期「帽子会松」，长期减排投资就没有对手盘。其三，纯数量工具把全部成本冲击倒进价格：价格是投资信号，波动过大本身就是政策失败。缺口因此不是重选 \\(Q^\\*\\)，而是给帽子装上跨期的承诺与稳定装置。</p><p><span class="marginnote">数字实例：2006 年 4 月，欧盟公布 2005 年核证排放比发放的配额少约 6300 万吨（约 4%），配额价格一周出头就从约 30 欧元跌到 10 欧元附近，此后一路走向近零。市场用一次崩盘演示了「稀缺不真」是什么样子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件装置。跨期银行：许可可跨期持有，把单期帽连成跨期路径，企业自己选择何时减排；帽子的长期形状靠线性缩减系数逐年收紧（EU 从每年 1.74% 收到 4.3%）。自动调节：市场稳定储备（MSR，2019 年运行）盯流通配额总量——高于 8.33 亿吨时每年按流通量的固定比例抽入储备，低于 4 亿吨时向拍卖放回，储备中超额部分自 2023 年起注销；「改总量」从立法程序搬进预置规则。价格保险：设价格下限与上限，区间内仍钉数量、触界后转钉价格——Roberts 与 Spence 1976 年提出的混合工具，Weitzman 判据在两个极端各取一半。</p>',8)),(e(),o(l,null,{default:a(()=>[r(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E9%9D%99%E6%80%81%E5%B8%BD%20Q*%22%5D%20--%3E%20TIME%5B%22%E8%B7%A8%E6%9C%9F%3A%20banking%20%2B%20%E9%80%90%E5%B9%B4%E6%94%B6%E7%B4%A7%22%5D%0A%20%20TIME%20--%3E%20INFO%5B%22%E6%96%B0%E4%BF%A1%E6%81%AF%3A%20%E7%9C%9F%E5%AE%9E%E7%A8%80%E7%BC%BA%E5%BA%A6%E6%BC%82%E7%A7%BB%22%5D%0A%20%20INFO%20--%3E%20MSR%5B%22%E5%B8%82%E5%9C%BA%E7%A8%B3%E5%AE%9A%E5%82%A8%E5%A4%87%3A%20%E8%A7%84%E5%88%99%E5%8C%96%E6%8A%BD%E6%94%BE%E4%B8%8E%E6%B3%A8%E9%94%80%22%5D%0A%20%20TIME%20--%3E%20COLLAR%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E9%99%90%E4%B8%8E%E4%B8%8A%E9%99%90%22%5D%0A%20%20MSR%20--%3E%20CRED%5B%22%E7%A8%80%E7%BC%BA%E6%80%A7%E7%9A%84%E5%8F%AF%E4%BF%A1%E6%89%BF%E8%AF%BA%22%5D%0A%20%20COLLAR%20--%3E%20CRED%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"MSR 为什么能救价格：它改变的不是当期供给，而是对「总量将如何演化」的预期——企业预期的是规则而不是下一次政治博弈；承诺机制从「承诺不动」换成「承诺怎样动」，这是后面几课补贴退坡、财政承诺反复出现的同一族机制。collar 为什么不等于背叛数量工具：环境目标的确定性只在区间内被让渡，触界即恢复；让渡换来的是价格无限波动的政治风险出清。分配侧的深化同样通过激励反馈进排放：祖父制把租金给在位者并惩罚新进入者；基准制按效率分配，但基准若按期下调，就把「补贴减排」变成「补贴产量」；电力部门拿免费配额却按机会成本定价，把配额租金转进电价——免费分配与竞争市场的联合产物，不是意外。",-1)),(e(),o(l,null,{default:a(()=>[r(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E6%AF%8F%E5%B9%B4%E7%BB%9F%E8%AE%A1%E6%B5%81%E9%80%9A%E9%85%8D%E9%A2%9D%E6%80%BB%E9%87%8F%22%5D%20--%3E%20HI%7B%22%E9%AB%98%E4%BA%8E%208.33%20%E4%BA%BF%E5%90%A8%EF%BC%9F%22%7D%0A%20%20HI%20--%3E%7C%22%E6%98%AF%22%7C%20ABS%5B%22%E6%8C%89%E6%B5%81%E9%80%9A%E9%87%8F%E5%9B%BA%E5%AE%9A%E6%AF%94%E4%BE%8B%E6%8A%BD%E5%85%A5%E5%82%A8%E5%A4%87%22%5D%0A%20%20MON%20--%3E%20LO%7B%22%E4%BD%8E%E4%BA%8E%204%20%E4%BA%BF%E5%90%A8%EF%BC%9F%22%7D%0A%20%20LO%20--%3E%7C%22%E6%98%AF%22%7C%20REL%5B%22%E5%90%91%E6%8B%8D%E5%8D%96%E6%94%BE%E5%9B%9E%E4%B8%80%E9%83%A8%E5%88%86%22%5D%0A%20%20ABS%20--%3E%20CAN%5B%22%E5%82%A8%E5%A4%87%E4%B8%AD%E8%B6%85%E9%A2%9D%E9%83%A8%E5%88%86%E8%87%AA%202023%20%E5%B9%B4%E8%B5%B7%E6%B3%A8%E9%94%80%22%5D%0A%20%20CAN%20--%3E%20TIGHT%5B%22%E6%80%BB%E9%87%8F%E5%AE%9E%E9%99%85%E6%94%B6%E7%B4%A7%EF%BC%9A%E7%A8%80%E7%BC%BA%E6%80%A7%E6%9B%B4%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20REL%20--%3E%20STABLE%5B%22%E4%BE%9B%E7%BB%99%E5%9B%9E%E8%A1%A5%EF%BC%9A%E4%BB%B7%E6%A0%BC%E6%B3%A2%E5%8A%A8%E8%A2%AB%E7%86%A8%E5%B9%B3%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">术语翻译：跨期银行（banking）就是「配额可以存着明年用」，今年的帽子用不完不作废。单期帽子因此被连成一条跨期总量，企业自己挑最便宜的年份减排；承诺的对象也从「这一年」变成「这一整条路径」。</span></p><p><span class="marginnote">EU ETS 的每次收紧都是对着一次事故的修补：2006 年核证数据揭出超发、第一期价格归零；MSR 的 8.33 亿与 4 亿吨阈值、2023 年起的注销，都是把「政治修正」改写成「规则修正」的尝试。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MSR 不创造减排，只重排减排的时间路径，注销是唯一真正缩帽的动作。强度帽随产量浮动，价格信号天然更弱——上一课的斜率判据在这里变成制度差异。监测与核证是体系的底座：数据造假直接改写帽子的真实稀缺度，MRV 的行政能力是不进公式的前置条件。市场势力可囤积配额操纵价格；价格下限在政治压力下被击穿时，规则与政治谁赢是开放问题。泄漏与抵消本课只立门牌：跨境那半留给碳边境调节课，补贴与抵消质量的纠缠留给补贴课。</p><p><span class="marginnote">常见误区：以为 MSR 抽走配额就等于减排了。储备只改排放发生的时间——早减还是晚减；真正缩小总量的动作只有注销。把「价格稳住了」当成「排放减少了」，是混淆稳定装置与减排装置。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>真实 ETS 的核心难题是跨期可信：帽子是核证数据与承诺规则的函数，不是立法文本的函数。</li><li>banking 把单期帽连成跨期路径；线性缩减系数收紧帽子；MSR 把总量修正规则化。</li><li>价格 collar 区间内钉数量、触界转价格，是 Weitzman 判据的混合实现。</li><li>分配规则通过激励反馈进排放：祖父制、基准制、免费配额的机会成本转嫁各有一条暗道。</li><li>MSR 只重排时间，注销才缩帽；MRV 与市场势力是公式之外的前置条件。</li><li>出处：Montgomery 1972；Roberts &amp; Spence 1976；Weitzman 1974 见上一课；EU ETS 制度事实据官方口径。</li></ul>',7))])}const u=i(d,[["render",c]]);export{f as __pageData,u as default};
